#include "exotic/autonomy/governance/service.hpp"
#include <cassert>
#include <unordered_map>
using namespace exotic::autonomy;using namespace exotic::autonomy::governance;
class MemoryRepo:public GovernanceRepository{public:std::vector<ApprovalRequest>rq;std::vector<ApprovalDecision>ds;std::vector<CapabilityGrant>gs;std::vector<PolicyVersion>ps;std::vector<DecisionEvidence>es;bool stop{};ApprovalRequestId next_request_id()override{return rq.size()+1;}DecisionId next_decision_id()override{return ds.size()+1;}GrantId next_grant_id()override{return gs.size()+1;}PolicyId next_policy_id()override{return ps.size()+1;}EvidenceId next_evidence_id()override{return es.size()+1;}void save_request(const ApprovalRequest&r)override{for(auto&x:rq)if(x.id==r.id){x=r;return;}rq.push_back(r);}std::optional<ApprovalRequest>load_request(ApprovalRequestId id)override{for(auto&x:rq)if(x.id==id)return x;return{};}std::vector<ApprovalRequest>load_pending(TimePoint)override{std::vector<ApprovalRequest>v;for(auto&x:rq)if(x.status==ApprovalStatus::Pending)v.push_back(x);return v;}void append_decision(const ApprovalDecision&d)override{ds.push_back(d);}std::vector<ApprovalDecision>load_decisions(ApprovalRequestId id)override{std::vector<ApprovalDecision>v;for(auto&x:ds)if(x.request_id==id)v.push_back(x);return v;}void save_grant(const CapabilityGrant&g)override{gs.push_back(g);}std::vector<CapabilityGrant>load_grants(std::string_view id)override{std::vector<CapabilityGrant>v;for(auto&x:gs)if(x.subject_id==id)v.push_back(x);return v;}void save_policy(const PolicyVersion&p)override{ps.push_back(p);}std::vector<PolicyVersion>load_active_policies()override{return ps;}void append_evidence(const DecisionEvidence&e)override{es.push_back(e);}std::vector<DecisionEvidence>load_evidence(ApprovalRequestId id)override{std::vector<DecisionEvidence>v;for(auto&x:es)if(x.request_id==id)v.push_back(x);return v;}void set_emergency_stop(bool b,std::string_view,std::string_view)override{stop=b;}bool emergency_stop_active()override{return stop;}};
int main(){MemoryRepo r;GovernanceService s{r};ApprovalRequest q;q.proposal_id=7;q.requester_id="builder";q.required_approvals=2;q.require_distinct_roles=true;auto id=s.request_approval(q);Subject a{"alice",{"security"},{}};Subject b{"bob",{"finance"},{}};assert(s.decide(id,a,Vote::Approve,"safe")==ApprovalStatus::Pending);assert(s.decide(id,b,Vote::Approve,"funded")==ApprovalStatus::Approved);assert(r.load_evidence(id).size()>=3);s.emergency_stop("owner","test");assert(r.emergency_stop_active());}
